SourceCode.Declaration:
/// <summary>
/// Extension of DocuRef
/// </summary>
[ExtensionOf(tableStr(DocuRef))]
final class NDXDocuRef_tbl_Extension
{
}

Method.Source:
void update(RecId _interCompanyFromRecId)
{
    DocuValue docuValue;
    DocuRef docuRefOrig = this.orig();
    next update(_interCompanyFromRecId);

    if(this.RefCompanyId == 'RIC' && docuRefOrig.Name != this.Name)
    {
        docuValue = DocuValue::find(this.ValueRecId, true);
        if(docuValue)
        {
            NDXRicoReqDocuTransfer::transferToRico(this, docuValue, NDXRICODMSAction::AendBetr);
        }
    }
}

void delete(RecId _interCompanyFromRecId, boolean _useCreatedByUser)
{
    DocuValue docuValue = DocuValue::find(this.ValueRecId, true);
    next delete(_interCompanyFromRecId, _useCreatedByUser);
    NDXRicoReqDocuTransfer::transferToRico(this, docuValue, NDXRICODMSAction::Loeschen);
}
